CREATE SCHEMA "NORTHSTAR";
SET SCHEMA "NORTHSTAR";





-- Tables shared by more than one business scope stay in 
CREATE TABLE Locations (Id INTEGER PRIMARY KEY, Name NVARCHAR(255) NOT NULL, City NVARCHAR(255) NOT NULL, State NVARCHAR(255) NOT NULL);
CREATE TABLE Users (
    Id INTEGER PRIMARY KEY, FirstName NVARCHAR(255) NOT NULL, LastName NVARCHAR(255) NOT NULL, BirthDate NVARCHAR(255) NOT NULL,
    Gender NVARCHAR(255) NOT NULL, City NVARCHAR(255) NOT NULL, State NVARCHAR(255) NOT NULL);

-- SQLite cannot enforce foreign keys across attached schemas.
-- HR
CREATE TABLE Departments (Id INTEGER PRIMARY KEY, Name NVARCHAR(255) NOT NULL);
CREATE TABLE Employees (
    Id INTEGER PRIMARY KEY, FirstName NVARCHAR(255) NOT NULL, LastName NVARCHAR(255) NOT NULL,
    DepartmentId INTEGER NOT NULL, LocationId INTEGER NOT NULL, ManagerId INTEGER NULL,
    JobTitle NVARCHAR(255) NOT NULL, HireDate NVARCHAR(255) NOT NULL, Salary DECIMAL(18,4) NOT NULL, EmploymentType NVARCHAR(255) NOT NULL,
    FOREIGN KEY (LocationId) REFERENCES Locations (Id),
    FOREIGN KEY (ManagerId) REFERENCES Employees (Id));
CREATE TABLE PerformanceReviews (
    Id INTEGER PRIMARY KEY, EmployeeId INTEGER NOT NULL, ReviewYear INTEGER NOT NULL,
    Rating INTEGER NOT NULL, BonusAmount DECIMAL(18,4) NOT NULL);
CREATE TABLE LeaveRequests (
    Id INTEGER PRIMARY KEY, EmployeeId INTEGER NOT NULL, LeaveType NVARCHAR(255) NOT NULL,
    StartDate NVARCHAR(255) NOT NULL, Days INTEGER NOT NULL, Status NVARCHAR(255) NOT NULL);

-- Sales
CREATE TABLE Products (
    Id INTEGER PRIMARY KEY, Name NVARCHAR(255) NOT NULL, Category NVARCHAR(255) NOT NULL,
    UnitPrice DECIMAL(18,4) NOT NULL, CostPrice DECIMAL(18,4) NOT NULL);
CREATE TABLE Orders (
    Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL, SalesRepId INTEGER NOT NULL, OrderDate NVARCHAR(255) NOT NULL,
    Channel NVARCHAR(255) NOT NULL, Status NVARCHAR(255) NOT NULL);
CREATE TABLE OrderItems (
    Id INTEGER PRIMARY KEY, OrderId INTEGER NOT NULL, ProductId INTEGER NOT NULL,
    Quantity INTEGER NOT NULL, UnitPrice DECIMAL(18,4) NOT NULL, DiscountAmount DECIMAL(18,4) NOT NULL,
    FOREIGN KEY (OrderId) REFERENCES Orders (Id),
    FOREIGN KEY (ProductId) REFERENCES Products (Id));

-- Health care
CREATE TABLE Diagnoses (
    Id INTEGER PRIMARY KEY, Code NVARCHAR(255) NOT NULL, Name NVARCHAR(255) NOT NULL, Category NVARCHAR(255) NOT NULL, IsChronic INTEGER NOT NULL);
CREATE TABLE Visits (
    Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL, DoctorId INTEGER NOT NULL, LocationId INTEGER NOT NULL,
    VisitDate NVARCHAR(255) NOT NULL, VisitType NVARCHAR(255) NOT NULL, DiagnosisId INTEGER NOT NULL,
    DurationMinutes INTEGER NOT NULL, Charge DECIMAL(18,4) NOT NULL, Status NVARCHAR(255) NOT NULL,
    FOREIGN KEY (DiagnosisId) REFERENCES Diagnoses (Id));
CREATE TABLE LabResults (
    Id INTEGER PRIMARY KEY, VisitId INTEGER NOT NULL, TestName NVARCHAR(255) NOT NULL,
    ResultValue DECIMAL(18,4) NOT NULL, ReferenceMax DECIMAL(18,4) NOT NULL, IsAbnormal INTEGER NOT NULL,
    FOREIGN KEY (VisitId) REFERENCES Visits (Id));

-- Insurance
CREATE TABLE InsurancePlans (
    Id INTEGER PRIMARY KEY, Name NVARCHAR(255) NOT NULL, Tier NVARCHAR(255) NOT NULL, MonthlyPremium DECIMAL(18,4) NOT NULL,
    Deductible DECIMAL(18,4) NOT NULL, OutOfPocketMax DECIMAL(18,4) NOT NULL, CoinsuranceRate DECIMAL(18,4) NOT NULL);
CREATE TABLE Policies (
    Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL, PlanId INTEGER NOT NULL, AgentId INTEGER NOT NULL,
    StartDate NVARCHAR(255) NOT NULL, EndDate NVARCHAR(255) NULL, Status NVARCHAR(255) NOT NULL,
    FOREIGN KEY (PlanId) REFERENCES InsurancePlans (Id));
CREATE TABLE PremiumPayments (
    Id INTEGER PRIMARY KEY, PolicyId INTEGER NOT NULL, PaymentDate NVARCHAR(255) NOT NULL, Amount DECIMAL(18,4) NOT NULL, Status NVARCHAR(255) NOT NULL,
    FOREIGN KEY (PolicyId) REFERENCES Policies (Id));
CREATE TABLE Claims (
    Id INTEGER PRIMARY KEY, PolicyId INTEGER NOT NULL, VisitId INTEGER NOT NULL, ClaimDate NVARCHAR(255) NOT NULL,
    BilledAmount DECIMAL(18,4) NOT NULL, AllowedAmount DECIMAL(18,4) NOT NULL, PaidAmount DECIMAL(18,4) NOT NULL,
    Status NVARCHAR(255) NOT NULL, DenialReason NVARCHAR(255) NULL, ProcessedDate NVARCHAR(255) NULL,
    FOREIGN KEY (PolicyId) REFERENCES Policies (Id));

-- SQLite cannot declare foreign keys across attached schemas. Keep those
-- logical relationships here so schema discovery can return both schema keys.
CREATE TABLE __DynamicSqlRelations (
    RelationName VARCHAR(255) NOT NULL,
    SourceSchema NVARCHAR(255) NOT NULL,
    SourceTable NVARCHAR(255) NOT NULL,
    SourceColumn NVARCHAR(255) NOT NULL,
    TargetSchema NVARCHAR(255) NOT NULL,
    TargetTable NVARCHAR(255) NOT NULL,
    TargetColumn NVARCHAR(255) NOT NULL,
    Ordinal INTEGER NOT NULL,
    IsUnique INTEGER NOT NULL,
    PRIMARY KEY (RelationName, Ordinal));

-- Cross-domain relationships that SQLite stores as metadata are real SAP HANA foreign keys.
ALTER TABLE Employees ADD CONSTRAINT FK_Employees_Departments FOREIGN KEY (DepartmentId) REFERENCES Departments (Id);
ALTER TABLE PerformanceReviews ADD CONSTRAINT FK_PerformanceReviews_Employees FOREIGN KEY (EmployeeId) REFERENCES Employees (Id);
ALTER TABLE LeaveRequests ADD CONSTRAINT FK_LeaveRequests_Employees FOREIGN KEY (EmployeeId) REFERENCES Employees (Id);
ALTER TABLE Orders ADD CONSTRAINT FK_Orders_Users FOREIGN KEY (UserId) REFERENCES Users (Id);
ALTER TABLE Orders ADD CONSTRAINT FK_Orders_Employees FOREIGN KEY (SalesRepId) REFERENCES Employees (Id);
ALTER TABLE Visits ADD CONSTRAINT FK_Visits_Users FOREIGN KEY (UserId) REFERENCES Users (Id);
ALTER TABLE Visits ADD CONSTRAINT FK_Visits_Employees FOREIGN KEY (DoctorId) REFERENCES Employees (Id);
ALTER TABLE Visits ADD CONSTRAINT FK_Visits_Locations FOREIGN KEY (LocationId) REFERENCES Locations (Id);
ALTER TABLE Policies ADD CONSTRAINT FK_Policies_Users FOREIGN KEY (UserId) REFERENCES Users (Id);
ALTER TABLE Policies ADD CONSTRAINT FK_Policies_Employees FOREIGN KEY (AgentId) REFERENCES Employees (Id);
ALTER TABLE Claims ADD CONSTRAINT FK_Claims_Visits FOREIGN KEY (VisitId) REFERENCES Visits (Id);

